import{_ as a,o as t,c as o,a2 as l}from"./chunks/framework.DQbZ8cc1.js";const u=JSON.parse('{"title":"Production Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"docs/installation/production.md","filePath":"docs/installation/production.md"}'),r={name:"docs/installation/production.md"};function i(d,e,s,n,p,c){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="production-deployment" tabindex="-1">Production Deployment <a class="header-anchor" href="#production-deployment" aria-label="Permalink to “Production Deployment”">​</a></h1><p>Use this page after you have chosen an installation method.</p><h2 id="recommended-production-setup" tabindex="-1">Recommended Production Setup <a class="header-anchor" href="#recommended-production-setup" aria-label="Permalink to “Recommended Production Setup”">​</a></h2><ul><li>Use MySQL 8+.</li><li>Put Nginx, Caddy, or another reverse proxy in front of BBS-GO.</li><li>Enable HTTPS.</li><li>Persist and back up database, uploads, config, and logs.</li><li>Use systemd, supervisor, Docker, or your platform process manager to keep the service running.</li></ul><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to “Ports”">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Default external port</th></tr></thead><tbody><tr><td>Release package</td><td><code>8082</code></td></tr><tr><td>Docker</td><td><code>3000</code></td></tr></tbody></table><p>You can expose a public domain through a reverse proxy and keep the internal port private.</p><h2 id="data-to-back-up" tabindex="-1">Data to Back Up <a class="header-anchor" href="#data-to-back-up" aria-label="Permalink to “Data to Back Up”">​</a></h2><p>For release-package deployments:</p><ul><li>MySQL database or SQLite database</li><li><code>bbs-go.yaml</code></li><li><code>res/uploads</code></li><li>logs if you need audit/history retention</li></ul><p>For Docker deployments:</p><ul><li>MySQL volume if using built-in MySQL</li><li><code>/app/data</code></li><li><code>/app/logs</code></li><li><code>/app/res/uploads</code></li></ul><h2 id="reverse-proxy" tabindex="-1">Reverse Proxy <a class="header-anchor" href="#reverse-proxy" aria-label="Permalink to “Reverse Proxy”">​</a></h2><p>Configure your reverse proxy to forward requests to the BBS-GO service port.</p><p>Example target:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8082</span></span></code></pre></div><p>For Docker, the default host port is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:3000</span></span></code></pre></div><h2 id="upgrade-checklist" tabindex="-1">Upgrade Checklist <a class="header-anchor" href="#upgrade-checklist" aria-label="Permalink to “Upgrade Checklist”">​</a></h2><ol><li>Back up database and uploads.</li><li>Stop the old service.</li><li>Replace the release package or update the Docker image tag.</li><li>Start the new service.</li><li>Check site, admin dashboard, login, uploads, and major pages.</li></ol><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to “Related Docs”">​</a></h2><ul><li><a href="./release.html">Install with Release Package</a></li><li><a href="./docker.html">Install with Docker</a></li></ul>',22)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
